   1 /**
   2  * Flow Analysis Tool
   3  * 
   4  * Analyzes all existing Genkit flows and generates a comprehensive report
   5  * about their structure, complexity, and migration requirements.
   6  * 
   7  * Usage:
   8  *   npm run analyze-flows
   9  *   tsx scripts/migration/analyze-flows.ts
  10  */
  11 
  12 import * as fs from 'fs';
  13 import * as path from 'path';
  14 import { FlowAnalyzer } from '@/lib/migration/analyzer/FlowAnalyzer';
  15 
  16 interface FlowAnalysisReport {
  17   totalFlows: number;
  18   flowsByComplexity: {
  19     simple: string[];
  20     medium: string[];
  21     complex: string[];
  22   };
  23   flowsByCategory: Record<string, string[]>;
  24   migrationEstimate: {
  25     simple: number;    // hours
  26     medium: number;
  27     complex: number;
  28     total: number;
  29   };
  30   dependencies: {
  31     flowName: string;
  32     dependencies: string[];
  33   }[];
  34   warnings: string[];
  35 }
  36 
  37 async function analyzeFlows(): Promise<FlowAnalysisReport> {
  38   console.log('🔍 Starting flow analysis...\n');
  39 
  40   const flowsDir = path.join(process.cwd(), 'src/ai/flows');
  41   const flowFiles = fs.readdirSync(flowsDir)
  42     .filter(file => file.endsWith('.ts') && file !== 'index.ts');
  43 
  44   const analyzer = new FlowAnalyzer();
  45   const report: FlowAnalysisReport = {
  46     totalFlows: 0,
  47     flowsByComplexity: {
  48       simple: [],
  49       medium: [],
  50       complex: [],
  51     },
  52     flowsByCategory: {},
  53     migrationEstimate: {
  54       simple: 0,
  55       medium: 0,
  56       complex: 0,
  57       total: 0,
  58     },
  59     dependencies: [],
  60     warnings: [],
  61   };
  62 
  63   for (const file of flowFiles) {
  64     const flowPath = path.join(flowsDir, file);
  65     const flowName = file.replace('.ts', '');
  66 
  67     console.log(`📄 Analyzing: ${flowName}`);
  68 
  69     try {
  70       const analysis = await analyzer.analyzeFlow(flowPath);
  71       report.totalFlows++;
  72 
  73       // Categorize by complexity
  74       const complexity = analysis.complexity || 'medium';
  75       report.flowsByComplexity[complexity as keyof typeof report.flowsByComplexity].push(flowName);
  76 
  77       // Categorize by type
  78       const category = analysis.category || 'general';
  79       if (!report.flowsByCategory[category]) {
  80         report.flowsByCategory[category] = [];
  81       }
  82       report.flowsByCategory[category].push(flowName);
  83 
  84       // Track dependencies
  85       if (analysis.dependencies && analysis.dependencies.length > 0) {
  86         report.dependencies.push({
  87           flowName,
  88           dependencies: analysis.dependencies,
  89         });
  90       }
  91 
  92       // Collect warnings
  93       if (analysis.warnings) {
  94         report.warnings.push(...analysis.warnings.map(w => `${flowName}: ${w}`));
  95       }
  96 
  97       // Estimate migration time
  98       const estimateHours = {
  99         simple: 2,
 100         medium: 4,
 101         complex: 8,
 102       };
 103       report.migrationEstimate[complexity as keyof typeof estimateHours] += 
 104         estimateHours[complexity as keyof typeof estimateHours] || 4;
 105 
 106     } catch (error) {
 107       console.error(`❌ Error analyzing ${flowName}:`, error);
 108       report.warnings.push(`${flowName}: Failed to analyze - ${error}`);
 109     }
 110   }
 111 
 112   // Calculate totals
 113   report.migrationEstimate.total = 
 114     report.migrationEstimate.simple + 
 115     report.migrationEstimate.medium + 
 116     report.migrationEstimate.complex;
 117 
 118   return report;
 119 }
 120 
 121 function printReport(report: FlowAnalysisReport): void {
 122   console.log('\n' + '='.repeat(80));
 123   console.log('📊 FLOW ANALYSIS REPORT');
 124   console.log('='.repeat(80) + '\n');
 125 
 126   console.log(`Total Flows: ${report.totalFlows}\n`);
 127 
 128   console.log('Complexity Breakdown:');
 129   console.log(`  Simple (${report.flowsByComplexity.simple.length}): ${report.flowsByComplexity.simple.join(', ')}`);
 130   console.log(`  Medium (${report.flowsByComplexity.medium.length}): ${report.flowsByComplexity.medium.join(', ')}`);
 131   console.log(`  Complex (${report.flowsByComplexity.complex.length}): ${report.flowsByComplexity.complex.join(', ')}\n`);
 132 
 133   console.log('Category Breakdown:');
 134   Object.entries(report.flowsByCategory).forEach(([category, flows]) => {
 135     console.log(`  ${category} (${flows.length}): ${flows.join(', ')}`);
 136   });
 137 
 138   console.log('\nMigration Time Estimate:');
