 140   console.log(`  Medium flows: ${report.migrationEstimate.medium} hours`);
 141   console.log(`  Complex flows: ${report.migrationEstimate.complex} hours`);
 142   console.log(`  Total: ${report.migrationEstimate.total} hours (${(report.migrationEstimate.total / 8).toFixed(1)} days)\n`);
 143 
 144   if (report.dependencies.length > 0) {
 145     console.log('Flow Dependencies:');
 146     report.dependencies.forEach(({ flowName, dependencies }) => {
 147       console.log(`  ${flowName} → ${dependencies.join(', ')}`);
